				d = uint64(submittedSealsInEpoch[candidate]) * types.DiligenceDenominator / 2
			} else if !candiInfo.wasValidator {
				applyingRate = epochLength - 1
				if uint64(submittedSealsInEpoch[candidate]) > 2*(epochLength-1) {
